        "properties": {
          "content": {
            "description": "Content of the candidate memory.",
            "type": "string"
          },
          "namespace": {
            "description": "Restrict the duplicate scan to this namespace. Omit to scan all namespaces.",
            "type": "string"
          },
          "threshold": {
            "default": 0.85,
            "description": "Cosine similarity threshold for declaring a duplicate. Clamped to >= 0.5. Default 0.85 is tuned for MiniLM-L6-v2 — near-paraphrases land at 0.88+.",
            "maximum": 1.0,
            "minimum": 0.5,
            "type": "number"
          },
          "title": {
            "description": "Title of the candidate memory. Combined with `content` to form the embedding input, matching memory_store's encoding.",
            "type": "string"
          }
        },
        "required": [
          "title",
          "content"
        ],
        "type": "object"
      },
      "name": "memory_check_duplicate"
    },
